-- Compact Neon schema, forward-only; run after an exact legacy baseline copy.
-- Historical migrations and the public SHA-256 ledger remain unchanged.
BEGIN;
SET LOCAL search_path=findi,pg_catalog;
DROP SCHEMA IF EXISTS findi_inspection CASCADE;
DROP SCHEMA IF EXISTS findi_migration CASCADE;
DROP VIEW IF EXISTS findi.sql_connect_migration_status;
DROP VIEW IF EXISTS findi.latest_store_analytics;
CREATE TABLE findi.app_state (
 id text PRIMARY KEY CHECK(id='baseline'),
 status text NOT NULL CHECK(status IN ('building','ready')),
 manifest jsonb NOT NULL DEFAULT '{}', verified_at timestamptz
);
INSERT INTO findi.app_state(id,status,manifest,verified_at)
 SELECT 'baseline',CASE WHEN status='active' THEN 'ready' ELSE 'building' END,
 manifest - 'writesPaused',CASE WHEN status='active' THEN verified_at ELSE NULL END
 FROM findi.database_migration_state WHERE id='firestore-to-sql';
INSERT INTO findi.app_state(id,status) VALUES('baseline','building') ON CONFLICT(id) DO NOTHING;
ALTER TABLE findi.app_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_backend ON findi.app_state TO findi_backend USING(true);
GRANT SELECT ON findi.app_state TO findi_backend;
REVOKE ALL ON findi.app_state FROM PUBLIC;
ALTER TABLE findi.products ADD COLUMN features text[] NOT NULL DEFAULT '{}';
UPDATE findi.products p SET features=coalesce((SELECT array_agg(f.text ORDER BY f.position) FROM findi.product_features f WHERE f.product_id=p.id),'{}');
DO $$ BEGIN
 IF EXISTS(SELECT asset_id FROM findi.product_media GROUP BY asset_id HAVING count(*)>1)
 THEN RAISE EXCEPTION 'COMPACT_SHARED_MEDIA_REQUIRES_REVIEW'; END IF;
END $$;
ALTER TABLE findi.media_assets
 ADD COLUMN product_id text REFERENCES findi.products(id) ON DELETE CASCADE,
 ADD COLUMN position integer CHECK(position>=0),
 ADD COLUMN in_gallery boolean NOT NULL DEFAULT false,
 ADD COLUMN is_primary boolean NOT NULL DEFAULT false,
 ADD CONSTRAINT media_product_position CHECK((product_id IS NULL)=(position IS NULL));
UPDATE findi.media_assets m SET product_id=p.product_id,position=p.position,in_gallery=p.in_gallery,is_primary=p.is_primary FROM findi.product_media p WHERE p.asset_id=m.id;
CREATE UNIQUE INDEX media_product_position ON findi.media_assets(product_id,position) WHERE product_id IS NOT NULL;
CREATE UNIQUE INDEX media_product_primary ON findi.media_assets(product_id) WHERE is_primary;
CREATE OR REPLACE VIEW findi.public_products WITH(security_barrier=true) AS
 SELECT p.id,p.name,p.product_type,p.catalog_level,p.sale_unit,p.presentation,p.barcode,
 p.short_description,p.long_description,p.brand_id,COALESCE(b.name,p.legacy_brand_label,'Por especificar') AS brand,
 p.family_id,f.name AS family_name,s.id AS subcategory_id,s.name AS subcategory_name,c.id AS category_id,c.name AS category_name,
 p.logistics_weight_kg,p.logistics_volume_m3,p.units_per_pallet,
 m.url AS image_url,m.origin AS image_origin,m.ai_disclosure,r.path AS seo_path,p.updated_at
 FROM findi.products p JOIN findi.families f ON f.id=p.family_id
 JOIN findi.subcategories s ON s.id=f.subcategory_id JOIN findi.categories c ON c.id=s.category_id
 LEFT JOIN findi.brands b ON b.id=p.brand_id
 LEFT JOIN findi.media_assets m ON m.product_id=p.id AND m.is_primary
 LEFT JOIN findi.seo_routes r ON r.product_id=p.id AND r.is_canonical AND r.active
 WHERE p.status='activo' AND p.deleted_at IS NULL;
DROP TABLE findi.product_media;
DROP TABLE findi.product_features;
-- Only metadata changes below; immutable verification content is preserved byte-for-byte as JSON.
