CREATE VIEW findi.latest_store_analytics WITH(security_invoker=true) AS
 SELECT DISTINCT ON(store_id) * FROM findi.store_daily_analytics ORDER BY store_id,computed_at DESC,local_date DESC;
REVOKE ALL ON findi.latest_store_analytics FROM PUBLIC;
GRANT SELECT ON findi.latest_store_analytics TO findi_backend,findi_api;
DROP TABLE findi.source_replication_versions;
DROP TABLE findi.database_migration_state;
-- A store product is the store's price/stock/publication of a master product.
ALTER TABLE findi.offers RENAME TO store_products;
COMMENT ON TABLE findi.store_products IS 'Store catalog products: owned price, stock, condition, publication and photo gallery.';
CREATE OR REPLACE FUNCTION findi.check_item_offer_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=findi,pg_catalog,pg_temp AS $$
DECLARE offer_product text; offer_store text;
BEGIN
 IF NEW.selected_offer_id IS NOT NULL THEN
  SELECT product_id,store_id INTO offer_product,offer_store FROM findi.store_products WHERE id=NEW.selected_offer_id;
  IF (NEW.product_id IS NOT NULL AND NEW.product_id<>offer_product) OR
     (NEW.selected_store_id IS NOT NULL AND NEW.selected_store_id<>offer_store)
  THEN RAISE EXCEPTION 'QUOTATION_OFFER_IDENTITY_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
COMMIT;
